import {renderOverview} from './views.js';
import {summary,scope,filteredWorkCases,uniquePeople,openRequirements,nextAction,journeySteps,recommendations,CHAT_SUGGESTIONS,ACCEPTED,REGISTERED} from './workflow.js';

export function renderLanding({icon,btn}){
  return `<div class="landing"><header class="landing-header"><a href="#welcome" class="landing-brand">${icon('leaf')}ADMIRA<span>Setiap tahap, ada tindak lanjut.</span></a><span class="live-mark">Data simulasi</span></header><main id="main" class="landing-main" tabindex="-1"><section class="landing-hero"><div class="landing-copy"><span class="eyebrow">PENDAMPINGAN ADMISI & REGISTRASI AKADEMIK</span><h1>Langkah Menuju Kuliah,<br><em>Lebih Terarah.</em></h1><p>Pantau proses pendaftaran, selesaikan persyaratan, dan dapatkan bantuan saat kamu membutuhkannya.</p><div class="landing-actions"><button class="btn apricot" data-role="student">Coba Demo Calon Mahasiswa ${icon('arrow')}</button><button class="btn hero-secondary" data-role="staff">Coba Demo Petugas ${icon('arrow')}</button></div><p class="landing-disclosure">Demo interaktif dengan data latihan. Belum memakai autentikasi atau akun sungguhan.</p></div><div class="landing-preview" aria-label="Contoh perjalanan pendaftaran"><div class="preview-label"><span>PERJALANAN PENDAFTARAN</span><span class="pill green">Contoh tampilan</span></div><h2>Satu tujuan.<br>Langkah yang <em>jelas.</em></h2><ol>${[['Pendaftaran','Selesai'],['Seleksi','Selesai'],['Pengumuman','Selesai'],['Daftar ulang','Perlu tindakan'],['Aktivasi mahasiswa','Belum dibuka']].map(([name,status],i)=>`<li><span class="preview-step ${i<3?'done':i===3?'current':''}">${i<3?icon('check'):'0'+(i+1)}</span><div><strong>${name}</strong><small>${status}</small></div></li>`).join('')}</ol><div class="preview-next">${icon('file')} Lihat persyaratan dan langkah berikutnya</div></div></section><section class="landing-benefits" aria-label="Manfaat ADMIRA">${[['01','Ketahui posisi pendaftaranmu.','Status dan perjalanan penerimaan dalam satu tempat.'],['02','Lihat persyaratan dan tenggat berikutnya.','Tindakan yang sesuai dengan keadaan pendaftaranmu.'],['03','Dapatkan bantuan untuk menyelesaikan kendala.','Tiket dan pendampingan yang dapat ditindaklanjuti.']].map(([n,h,p])=>`<article><span>${n}</span><h2>${h}</h2><p>${p}</p></article>`).join('')}</section><section class="landing-explainer"><span class="eyebrow">TERHUBUNG DARI TEMUAN SAMPAI TINDAK LANJUT</span><h2>Kamu tahu langkahnya.<br>Petugas tahu <em>siapa yang perlu dibantu.</em></h2><p>Persyaratan, pemeriksaan, bantuan, dan evaluasi layanan memakai satu sumber data. Keputusan penerimaan tetap berada pada petugas berwenang.</p>${btn('Kenali ADMIRA','guide','secondary','book')}</section><footer class="landing-footer"><span>ADMIRA · Sistem pendampingan penerimaan mahasiswa</span><span>Data simulasi · Tanpa klaim hasil penerimaan nyata</span></footer></main><button class="chat-launcher" data-action="chat-open" aria-label="Tanya ADMIRA">${icon('help')}<span>Tanya ADMIRA</span></button></div>`;
}

const base=f=>({year:f.year,route:f.route,prodi:f.prodi,region:f.region});
export function renderDashboard(k){
  const {state,filters,esc,icon}=k, data=summary(state,base(filters)),m=data.counts;
  let html=renderOverview({...k,filters:base(filters)});
  const tiles=`<section class="stats stats-editorial summary-six" aria-label="Ringkasan terhubung">${data.tiles.map(t=>`<button class="stat ${t.id==='active'?'active-stat':''}" data-metric="${t.id}"><span class="stat-top">${t.title}${icon(t.id==='tickets'?'help':t.id==='open'?'tasks':'users')}</span><span class="stat-number">${t.value===null?'—':t.value}</span><span class="stat-foot">${t.unit==='tiket'?t.applications+' aplikasi terkait':t.value===null?'Pengenal orang belum lengkap':t.applications+' aplikasi · orang unik'}</span><span class="stat-drill">Buka rincian ${icon('arrow')}</span></button>`).join('')}</section><p class="count-definition">${data.people===null?'Jumlah orang belum dapat dipastikan.':`${data.people} pendaftar unik dari ${m.total} aplikasi berdasarkan ID orang pada dataset demo.`} Kategori saling bertumpang tindih; tidak dijumlahkan menjadi total baru.</p>`;
  html=html.replace(/<section class="stats stats-editorial"[\s\S]*?<\/section>/,tiles);
  const amounts=[m.total,m.accepted,m.registered,m.active],denominators=[m.total,m.final,m.accepted,m.registered],labels=['seluruh aplikasi','hasil seleksi final','diterima pada tahap daftar ulang','selesai daftar ulang'];
  const pipeline=`<div class="pipeline-chart">${['Pendaftaran','Diterima','Daftar ulang','Mahasiswa aktif'].map((name,i)=>`<button class="pipeline-row" data-metric="${['total','accepted','registered','active'][i]}"><span class="pipeline-label"><span class="pipeline-index">0${i+1}</span>${name}</span><span class="pipeline-track"><span class="pipeline-bar step-${i}" style="display:block;width:${m.total?amounts[i]/m.total*100:0}%"></span><strong>${amounts[i]}</strong></span><span class="pipeline-percent">${denominators[i]?Math.round(amounts[i]/denominators[i]*100)+'%':'—'}<small>${amounts[i]}/${denominators[i]}</small></span><span class="pipeline-denominator">${labels[i]} · unit aplikasi</span></button>`).join('')}</div><div class="pipeline-legend">`;
  html=html.replace(/<div class="pipeline-chart">[\s\S]*?<div class="pipeline-legend">/,pipeline);
  html=html.replace(/<strong>\d+ tiket terbuka<\/strong>/,`<strong>${data.tickets.length} tiket terbuka</strong>`);
  const period=`<div class="period-explanation">${icon('clock')}<span><strong>Periode masih berjalan.</strong> ${data.ongoing} diterima belum selesai daftar ulang dan masih dalam jadwal atau belum memiliki tenggat. ${data.passed} melewati tenggat dan perlu ditinjau; tidak otomatis dibatalkan.</span></div>`;
  html=html.replace('<div class="dashboard-grid editorial-grid">',period+'<div class="dashboard-grid editorial-grid">');
  return html+`<section class="evaluation-invite"><div><span class="eyebrow">DARI DATA KE PERBAIKAN LAYANAN</span><h2>Temuan hari ini,<br>rencana yang dapat ditelusuri.</h2><p>Tinjau bukti, tentukan pelaksana, dan catat hasil evaluasi.</p></div><button class="btn" data-page="evaluation">Evaluasi dan Rekomendasi ${icon('arrow')}</button></section>`;
}

export function renderJourney(k,c){const {state,intro,demo,btn,esc,pill,fmt,icon,journeyMarkup}=k;
  const action=nextAction(state,c.id);
  return intro('LANGKAH SAYA','Sekarang, apa langkahku?','Periksa setiap persyaratan, catatan pemeriksaan, dan riwayat pengajuan.',btn('Panduan cetak','print-guide','secondary','download')+btn('Kalender tenggat','download-calendar','secondary','calendar'))+demo()+`<div class="candidate-identity"><strong>${esc(c.name)}</strong><span>${esc(c.prodi)} · Jalur ${esc(c.route||'belum tersedia')} · ${esc(c.id)}</span>${pill(c.source)}</div><div class="workflow-next"><span class="eyebrow">TINDAKAN YANG SESUAI STATUSMU</span><h2>${esc(action.title)}</h2><p>${esc(action.text)}</p><small>Data diperbarui ${fmt(state.updatedAt)} · jadwal simulasi</small></div><div class="two-col"><section class="panel requirements-panel"><div class="panel-head"><div><h2>Daftar persyaratan</h2><p>Status setiap dokumen mengikuti pengiriman dan pemeriksaan.</p></div>${pill(c.status)}</div>${c.requirements.map(r=>`<article class="requirement" id="req-${r.id}"><div class="requirement-heading"><h3>${esc(r.name)}</h3>${pill(r.applicable?r.status:'Tidak berlaku')}</div><p class="requirement-deadline">${icon('calendar')} ${fmt(r.deadline)} · simulasi</p>${r.reason?`<div class="inline-alert"><strong>Catatan petugas</strong><br>${esc(r.reason)}</div>`:''}${r.file?`<div class="file-row">${esc(r.file.name)} · ${Math.ceil(r.file.size/1024)} KB<br><small>Metadata demo; isi berkas tidak diunggah ke server.</small></div>`:''}${r.applicable&&c.source==='Diterima'&&['Perlu tindakan','Perlu perbaikan'].includes(r.status)?`<form class="requirement-upload" data-requirement="${r.id}"><label class="field">${r.status==='Perlu perbaikan'?'Pilih dokumen perbaikan':'Pilih berkas'}<input name="document" type="file" accept=".pdf,.jpg,.jpeg,.png" required><small>PDF, JPG, atau PNG · maksimum 5 MB · gunakan berkas contoh.</small></label><p class="error" role="alert"></p><button type="submit" class="btn">${r.status==='Perlu perbaikan'?'Kirim perbaikan':'Kirim untuk diperiksa'} ${icon('arrow')}</button></form>`:`<p class="requirement-note">${r.status==='Menunggu verifikasi'?'Dokumen sudah diterima. Tidak perlu dikirim ulang selama diperiksa.':r.status==='Selesai'?'Persyaratan sudah diverifikasi petugas.':'Kewajiban ini belum berlaku pada status pendaftaranmu.'}</p>`}</article>`).join('')}</section><aside class="stack"><section class="panel"><h2>Perjalanan pendaftaran</h2>${journeyMarkup(c)}<p class="login-note">Tidak ada persentase progres buatan. Setiap tahap mengikuti status sumber.</p></section><section class="panel"><h2>Ada yang menghambat?</h2><p>Jelaskan kendalamu kepada petugas atau tanyakan status melalui FAQ terstruktur.</p>${btn('Minta bantuan','new-ticket','secondary','help')}<button class="text-btn section-gap" data-action="chat-open">Tanya ADMIRA ${icon('arrow')}</button></section></aside></div><section class="panel section-gap"><h2>Riwayat pengiriman & pemeriksaan</h2>${c.history.length?`<ol class="document-history">${c.history.map(h=>`<li><strong>${esc(h.requirement)} · ${esc(h.status)}</strong><small>${esc(h.actor)} · ${fmt(h.time)}</small>${h.file?`<p>${esc(h.file.name)}</p>`:''}${h.reason?`<p>${esc(h.reason)}</p>`:''}</li>`).join('')}</ol>`:`<p>Belum ada pengiriman baru pada simulasi ini. Status awal berasal dari data latihan.</p>`}</section>`;
}
export function renderJourneySteps(c,icon,esc){return `<ol class="journey">${journeySteps(c).map((step,i)=>`<li><span class="step-number ${step.status==='Selesai'?'done':step.status==='Perlu tindakan'||step.status==='Perlu perbaikan'||step.status==='Sedang diproses'?'current':''}">${step.status==='Selesai'?icon('check'):i+1}</span><div><h3>${esc(step.name)}</h3><p>${esc(step.status)}</p></div></li>`).join('')}</ol>`;}

export function renderCaseTable(k,rows,limit=Infinity){const {state,esc,pill,icon,fmt}=k;if(!rows.length)return `<div class="empty"><h3>Tidak ada calon mahasiswa pada cakupan ini.</h3><p>Ubah filter atau pilih kategori lain. Tidak ada data tambahan yang dibuat.</p></div>`;
  return `<div class="table-wrap"><table class="responsive-table work-table"><thead><tr><th>CALON MAHASISWA / APLIKASI</th><th>PRODI / JALUR</th><th>TAHAP & KEWAJIBAN</th><th>TENGGAT</th><th>KENDALA DILAPORKAN</th><th>PETUGAS</th><th>TINDAK LANJUT TERAKHIR</th><th>TINDAKAN</th></tr></thead><tbody>${rows.slice(0,limit).map(c=>{const tickets=state.tickets.filter(t=>t.caseId===c.id&&t.status!=='Selesai');const reqs=openRequirements(c);const waiting=c.requirements.filter(r=>r.applicable&&r.status==='Menunggu verifikasi');return `<tr><td><strong>${esc(c.name)}</strong><small>${esc(c.id)} · ${c.personId?'ID orang tersedia':'ID orang belum tersedia'}<br>Status sumber: ${esc(c.source)}</small></td><td data-label="Prodi / jalur">${esc(c.prodi)}<small>${esc(c.route||'Belum tersedia')}</small></td><td data-label="Tahap & kewajiban">${esc(c.stage===3?'Aktivasi mahasiswa':c.stage===2?'Daftar ulang':'Seleksi / pengumuman')}<small>${reqs.length?reqs.map(r=>esc(r.name)).join(', '):waiting.length?'Dokumen menunggu pemeriksaan':esc(c.status)}</small>${pill(c.status)}</td><td data-label="Tenggat">${fmt(c.deadline,false)}${c.deadline&&new Date(c.deadline)<new Date(state.now)&&reqs.length?'<small>Terlewati · perlu ditinjau</small>':''}</td><td data-label="Kendala">${tickets.length?tickets.map(t=>esc(t.category)+' · '+esc(t.id)).join('<br>'):'Belum ada kendala dilaporkan'}</td><td data-label="Petugas">${esc(c.owner)}</td><td data-label="Tindak lanjut terakhir">${c.lastFollowup?fmt(c.lastFollowup,false):'Belum ada tindak lanjut'}</td><td><button class="table-link" data-case="${esc(c.id)}" aria-label="Buka kasus ${esc(c.name)}">${icon('arrow')}</button></td></tr>`;}).join('')}</tbody></table></div>`;
}
export function renderFollowup(k){const {state,filters,intro,demo,filterbar,esc,icon,pill,fmt}=k,rows=filteredWorkCases(state,filters);const names={total:'Pendaftar unik',accepted:'Dinyatakan diterima',registered:'Daftar ulang selesai',active:'Mahasiswa aktif',open:'Kewajiban terbuka',tickets:'Tiket belum selesai',review:'Menunggu pemeriksaan',overdue:'Tenggat terlewati'};
  const raw=summary(state,base(filters)),ids=new Set(rows.map(c=>c.id));const tickets=raw.tickets.filter(t=>ids.has(t.caseId));
  return intro('TINDAK LANJUT','Siapa yang perlu dibantu?','Telusuri angka ke calon mahasiswa, kewajiban, tenggat, dan penanggung jawabnya.')+demo()+filterbar(true)+`<div class="tabs">${[['','Semua aplikasi'],['open','Kewajiban terbuka'],['review','Menunggu pemeriksaan'],['tickets','Tiket terbuka'],['overdue','Tenggat terlewati']].map(([id,label])=>`<button class="tab ${filters.metric===id?'active':''}" data-metric="${id}">${label}</button>`).join('')}</div>${filters.metric?`<div class="metric-context"><strong>${esc(names[filters.metric]||'Cakupan terpilih')}</strong><span>${uniquePeople(rows)??'Belum dapat dihitung'} orang unik · ${rows.length} aplikasi${filters.metric==='tickets'?' · '+tickets.length+' tiket terbuka':''}</span><button class="text-btn" data-metric="">Hapus kategori ${icon('close')}</button></div>`:''}${filters.metric==='tickets'?`<section class="panel section-gap"><h2>Tiket pembentuk angka</h2>${tickets.length?tickets.map(t=>`<div class="list-row"><div class="grow"><h3>${esc(t.id)} · ${esc(state.cases.find(c=>c.id===t.caseId)?.name)}</h3><p>${esc(t.text)}</p><small>${esc(t.owner)} · ${fmt(t.created,false)}</small></div><div>${pill(t.status)}<br><button class="text-btn" data-ticket="${t.id}">Buka tiket ${icon('arrow')}</button></div></div>`).join(''):'<p>Tidak ada tiket terbuka pada cakupan ini.</p>'}</section>`:''}<section class="panel queue-panel section-gap"><div class="panel-head"><div><h2>Daftar calon mahasiswa & aplikasi</h2><p>${rows.length} aplikasi sesuai filter. Satu orang dapat memiliki lebih dari satu aplikasi.</p></div></div>${renderCaseTable(k,rows.sort((a,b)=>new Date(a.deadline||'2099-01-01')-new Date(b.deadline||'2099-01-01')))}</section><p class="count-definition">Prioritas dapat ditinjau dari tenggat, dokumen menunggu petugas, dan tiket yang belum ditangani. Melewati tenggat tidak membatalkan penerimaan otomatis.</p>`;
}

export function requirementReview(k,c){const {esc,pill,fmt}=k;
  return `<section class="case-requirements"><h3>Persyaratan & bukti pengajuan</h3><p class="login-note">Pemeriksaan ini adalah simulasi metadata. Isi berkas tidak tersimpan di server.</p>${c.requirements.filter(r=>r.applicable).map(r=>`<article class="requirement"><div class="requirement-heading"><h3>${esc(r.name)}</h3>${pill(r.status)}</div>${r.file?`<p class="file-row">${esc(r.file.name)} · ${Math.ceil(r.file.size/1024)} KB</p>`:'<p>Belum ada berkas diajukan.</p>'}${r.reason?`<p class="error">${esc(r.reason)}</p>`:''}${r.status==='Menunggu verifikasi'?`<form class="document-review" data-case-id="${c.id}" data-requirement="${r.id}"><label class="field">Hasil pemeriksaan<select name="decision" aria-label="Hasil pemeriksaan"><option value="Selesai">Dokumen sesuai</option><option value="Perlu perbaikan">Perlu perbaikan</option></select></label><label class="field">Kategori alasan<select name="reasonCode" aria-label="Kategori alasan"><option value="other">Lainnya / tidak berlaku</option><option value="unreadable">Dokumen tidak terbaca</option><option value="incomplete">Informasi dokumen belum lengkap</option></select></label><label class="field">Catatan petugas<textarea name="reason" maxlength="1000" placeholder="Wajib diisi bila perlu perbaikan"></textarea></label><p class="error" role="alert"></p><button class="btn" type="submit">Simpan hasil pemeriksaan</button></form>`:''}<small>${r.history.length?'Pembaruan '+fmt(r.history[0].time,false):'Status awal data latihan'}</small></article>`).join('')}</section>`;
}

export function renderChat(k,role){const {state,esc,btn,fmt}=k,key=role==='public'?'public':role;const messages=state.chats[key]||[];
  return `<div class="chat-disclosure"><strong>Demo FAQ terstruktur</strong><p>Jawaban dari panduan latihan dan status demo milikmu. Belum memakai AI atau akun nyata.</p></div><div class="chat-messages" aria-label="Percakapan Tanya ADMIRA">${messages.length?messages.map(m=>`<article class="chat-message ${m.actor==='user'?'from-user':'from-assistant'}"><strong>${m.actor==='user'?'Kamu':'Tanya ADMIRA'}</strong><p>${esc(m.text)}</p>${m.actor==='assistant'?`<small>${m.kind==='personal'?'Informasi pribadi demo':m.kind==='unavailable'?'Informasi belum dapat dipastikan':'Informasi umum'}<br>Sumber: ${esc(m.source)}<br>Diperbarui ${fmt(m.updatedAt)}</small><div class="chat-response-actions">${(m.actions||[]).map(a=>btn(esc(a.label),a.action,'secondary')).join('')}</div>`:''}</article>`).join(''):'<p>Pilih pertanyaan atau tulis pertanyaan tentang pendaftaran.</p>'}</div><div class="chat-suggestions">${CHAT_SUGGESTIONS.map((q,i)=>`<button data-chat-question="${i}">${esc(q)}</button>`).join('')}</div><form id="chat-form"><label class="field">Pertanyaanmu<input name="question" required maxlength="500" autocomplete="off" placeholder="Contoh: apa langkah saya berikutnya?"></label><div class="actions"><button class="btn" type="submit">Tanyakan</button>${role==='student'?btn('Teruskan ke petugas','chat-handoff','secondary'):''}</div></form>`;
}

export function renderEvaluation(k){const {state,filters,intro,demo,filterbar,esc,fmt,pill,icon,evalTab}=k;
  const recs=recommendations(state,base(filters));const plans=state.actionPlans.filter(p=>Object.entries(base(filters)).every(([key,value])=>!value||p.scope[key]===value));
  return intro('EVALUASI DAN REKOMENDASI','Dari temuan, menuju perbaikan.','Tinjau bukti, simpan usulan tindakan, dan catat hasilnya. Keputusan tetap memerlukan peninjauan manusia.')+demo()+filterbar()+`<div class="tabs"><button class="tab ${evalTab==='findings'?'active':''}" data-eval-tab="findings">Temuan & usulan</button><button class="tab ${evalTab==='plans'?'active':''}" data-eval-tab="plans">Rencana tindakan (${plans.length})</button></div>${evalTab==='plans'?`<section class="panel"><div class="panel-head"><div><h2>Register tindakan yang dapat ditelusuri</h2><p>Dasar rekomendasi disimpan sebagai snapshot saat rencana dibuat.</p></div></div>${plans.length?plans.map(p=>`<article class="plan-row"><div><span class="eyebrow">${esc(p.scope.year||'Semua periode')} · ${esc(p.owner)}</span><h3>${esc(p.title)}</h3><p>${esc(p.proposal)}</p><small>Evaluasi ${esc(p.reviewDate)} · ${esc(p.indicator)}</small>${p.result?`<p class="plan-result">Hasil: ${esc(p.result)}</p>`:''}</div><div>${pill(p.status)}<button class="text-btn" data-plan="${p.id}">Buka rencana ${icon('arrow')}</button></div></article>`).join(''):'<div class="empty"><h3>Belum ada rencana pada cakupan ini.</h3><p>Tinjau rekomendasi lalu simpan usulan menjadi rencana tindakan.</p></div>'}</section>`:`<div class="recommendations">${recs.map((r,i)=>`<article class="panel recommendation"><div class="recommendation-top"><span class="section-number">0${i+1}</span><span class="pill">Perlu ditinjau</span></div><h2>${esc(r.title)}</h2><dl><dt>Temuan · periode ${esc(r.period)}</dt><dd>${esc(r.finding)}</dd><dt>Angka & dasar perhitungan</dt><dd>${esc(r.evidence)}</dd><dt>Kelompok / proses</dt><dd>${esc(r.target)}</dd><dt>Usulan tindakan</dt><dd>${esc(r.proposal)}</dd><dt>Pelaksana & waktu evaluasi</dt><dd>${plans.find(p=>p.recommendationId===r.id&&p.status!=='Ditutup')?esc(plans.find(p=>p.recommendationId===r.id&&p.status!=='Ditutup').owner)+' · '+esc(plans.find(p=>p.recommendationId===r.id&&p.status!=='Ditutup').reviewDate):'Belum ditetapkan. Tentukan saat menyusun rencana tindakan.'}</dd><dt>Indikator evaluasi</dt><dd>${esc(r.indicator)}</dd></dl><div class="recommendation-limit">${icon('info')}${esc(r.limit)}</div><small>Sumber: ${esc(r.source)} · diperbarui ${fmt(r.updatedAt)}</small><button class="btn secondary" data-recommendation="${r.id}">Jadikan rencana tindakan ${icon('arrow')}</button></article>`).join('')}</div>`}`;
}
